#!/usr/bin/env Rscript

# ==========================================================
# Script   : historical_d13_nested_model.R
# Purpose  : Retain an exploratory or secondary historical analysis for transparent provenance
# Inputs   : see data/README.md and config/paths.yml
# Outputs  : historical workspace outputs; not generated by run_all.sh
# Paper    : Not a final-results workflow entry point
# Seed     : see config/params.yml
# Runtime  : not benchmarked in the public release
# Last run : see provenance/source_provenance.csv
# Source   : guarded-workspace:scripts/run_v31_d13_nested_model.R
# ==========================================================
# V31-D13 full-pipeline nested validation and bootstrap. Candidate genes are
# never supplied as a vector: every fit derives them from its own selected
# B-cell-related WGCNA module. The runner is intentionally fail-closed.
suppressPackageStartupMessages({library(SummarizedExperiment); library(DESeq2); library(WGCNA); library(GSVA); library(glmnet); library(survival); library(jsonlite)})
options(stringsAsFactors = FALSE); allowWGCNAThreads(nThreads = 4)
source("scripts/v31_d13_model_factory.R", local = TRUE)
source("scripts/v31_d13_train_derived_vst_transfer.R", local = TRUE)
need <- function(ok, ...) if (!isTRUE(ok)) stop(sprintf(...), call. = FALSE)
atomic_write_rds <- function(x, path) { dir.create(dirname(path), recursive = TRUE, showWarnings = FALSE); tmp <- paste0(path, ".tmp-", Sys.getpid()); saveRDS(x, tmp); need(file.rename(tmp, path), "cannot atomically install %s", path) }
atomic_write_tsv <- function(x, path) { dir.create(dirname(path), recursive = TRUE, showWarnings = FALSE); tmp <- paste0(path, ".tmp-", Sys.getpid()); write.table(x, tmp, sep = "\t", quote = FALSE, row.names = FALSE); need(file.rename(tmp, path), "cannot atomically install %s", path) }
arg <- commandArgs(trailingOnly = TRUE)
need(length(arg) == 2L && arg[[1L]] %in% c("--pilot", "--execute"), "Usage: --pilot|--execute FROZEN_CONTRACT.json")
contract <- read_contract(arg[[2L]]); validate_d13_contract(contract, getwd(), TRUE)
contract$bcell_trait$components <- as.character(unlist(contract$bcell_trait$components, use.names = FALSE))
OUT <- dirname(contract$outputs$outer_predictions); dir.create(OUT, recursive = TRUE, showWarnings = FALSE)
CP <- file.path(OUT, "checkpoints"); dir.create(CP, recursive = TRUE, showWarnings = FALSE)
seed <- contract$resampling$fold_seed
trait_sets <- read_bcell_trait_definition(contract$inputs$fig1_bcell_trait_definition$path, contract$bcell_trait$definition_id, contract$bcell_trait$definition_version, contract$bcell_trait$components)
se <- readRDS(contract$inputs$raw_counts$path); sy <- read.csv(contract$inputs$survival$path, check.names = FALSE)
pat0 <- as.character(colData(se)$patient); sy$patient_id <- substr(as.character(sy$sample_id), 1L, 12L)
need(!anyDuplicated(pat0) && !anyDuplicated(sy$patient_id), "raw/OS patient identifiers must each be unique")
use <- pat0 %in% sy$patient_id
need(sum(use) == contract$roster$expected_patients && all(sy$patient_id %in% pat0), "raw/OS roster must be the frozen exact patient intersection")
pat <- pat0[use]; sy <- sy[match(pat, sy$patient_id), , drop = FALSE]; raw0 <- assays(se)$unstranded[, use, drop = FALSE]; anno0 <- as.data.frame(rowData(se))
need(ncol(raw0) == contract$roster$expected_patients && nrow(sy) == contract$roster$expected_patients && sum(sy$OS_status == 1L) == contract$roster$expected_events, "frozen OS roster drift")
atomic_write_tsv(data.frame(patient_id = pat, sample_id = sy$sample_id, OS_time = sy$OS_time, OS_status = sy$OS_status, stringsAsFactors = FALSE), file.path(OUT, "D13_FROZEN_476_PATIENT_ROSTER.tsv"))
ens0 <- sub("\\..*$", "", as.character(anno0$gene_id)); sym0 <- as.character(anno0$gene_name); pc0 <- as.character(anno0$gene_type) == "protein_coding"
strat_folds <- function(status, k, seed) { set.seed(seed); out <- integer(length(status)); for (z in sort(unique(status))) { ix <- which(status == z); out[ix] <- sample(rep(seq_len(k), length.out = length(ix))) }; out }
prep <- function(ix, ids) { raw <- raw0[, ix, drop = FALSE]; colnames(raw) <- ids; pass <- pc0 & !is.na(sym0) & nzchar(sym0) & !is.na(ens0) & nzchar(ens0) & rowSums(raw >= contract$qc$min_count) >= ceiling(contract$qc$min_sample_fraction * ncol(raw)); mn <- rowMeans(raw); cand <- which(pass); cand <- cand[order(sym0[cand], -mn[cand], ens0[cand])]; keep <- cand[!duplicated(sym0[cand])]; list(idx = keep, ids = ens0[keep], symbols = sym0[keep], counts = raw[keep, , drop = FALSE]) }
concordance_or_fail <- function(time, status, score, tag, phase) { z <- tryCatch(survival::concordance(Surv(time, status) ~ score, reverse = TRUE)$concordance, error = function(e) NA_real_); if (!is.finite(z)) stop(sprintf("%s_%s_CONCORDANCE_UNAVAILABLE", tag, phase), call. = FALSE); z }
# Fits the whole specified pipeline on train_ix. Evaluation data are transformed
# only through training-derived quantities. Instance IDs permit bootstrap duplicates.
one_pipeline <- function(train_ix, train_ids, tag, eval_ix = integer(), eval_ids = character()) {
  p <- prep(train_ix, train_ids); need(length(p$idx) > 100L, "fold %s insufficient QC genes", tag); rownames(p$counts) <- p$ids
  fit <- fit_v31_train_vst(p$counts, colnames(p$counts)); tr <- transform_v31_training_partition(fit, p$counts); rownames(tr) <- p$ids
  # The source-bound Fig.1 B-cell trait is a training-only biological
  # measurement and must use every QC-eligible, uniquely mapped VST gene.  It
  # is intentionally distinct from the subsequent high-MAD WGCNA feature
  # universe: restricting ssGSEA to WGCNA genes can discard valid component
  # genes in patient bootstrap resamples.
  trait_ex <- t(tr); colnames(trait_ex) <- p$symbols; need(!anyDuplicated(colnames(trait_ex)), "training trait ID uniqueness failure")
  sets <- lapply(trait_sets, function(g) intersect(g, colnames(trait_ex))); need(all(lengths(sets) >= 3L), "fold %s B-cell trait cannot be computed after QC", tag)
  ss <- GSVA::gsva(ssgseaParam(exprData = t(trait_ex), geneSets = sets, minSize = 3L, normalize = TRUE), verbose = FALSE); ss <- t(scale(t(ss))); ss <- t(ss); colnames(ss) <- contract$bcell_trait$components; rownames(ss) <- rownames(trait_ex)
  # WGCNA itself remains restricted to the prespecified top-MAD training genes.
  madx <- apply(tr, 1L, mad); nmad <- ceiling(contract$qc$mad_fraction * length(madx)); ni <- order(-madx, p$ids)[seq_len(nmad)]
  ex <- t(tr[ni, , drop = FALSE]); colnames(ex) <- p$symbols[ni]; need(!anyDuplicated(colnames(ex)), "training WGCNA ID uniqueness failure")
  pwv <- c(1:10, seq(12, 20, 2)); sft <- pickSoftThreshold(ex, powerVector = pwv, networkType = contract$wgcna$network_type, corFnc = contract$wgcna$correlation, verbose = 0); sf <- as.data.frame(sft$fitIndices); hit <- which(sf$SFT.R.sq >= 0.85); pw <- if (length(hit)) sf$Power[hit[[1L]]] else sf$Power[which.max(sf$SFT.R.sq)]
  net <- blockwiseModules(ex, power = pw, networkType = contract$wgcna$network_type, TOMType = "unsigned", corType = contract$wgcna$correlation, minModuleSize = contract$wgcna$min_module_size, reassignThreshold = 0, mergeCutHeight = contract$wgcna$merge_cut_height, numericLabels = FALSE, pamRespectsDendro = FALSE, maxBlockSize = 20000L, nThreads = 4L, verbose = 0)
  co <- as.character(net$colors); names(co) <- colnames(ex); cc <- cor(net$MEs, ss, use = "pairwise.complete.obs")
  long <- do.call(rbind, lapply(rownames(cc), function(m) data.frame(module_id = m, trait_component = colnames(cc), correlation = as.numeric(cc[m, ]), is_grey = tolower(sub("^ME", "", m)) == "grey", stringsAsFactors = FALSE)))
  chosen <- select_bcell_module(long, components = contract$bcell_trait$components, threshold = contract$wgcna$mean_abs_correlation_threshold, min_components = contract$wgcna$minimum_components_at_threshold); sel <- chosen$selected_module_id
  mem <- data.frame(gene_id = p$ids[ni], gene_symbol = colnames(ex), module_id = paste0("ME", co), qc_eligible = TRUE, id_unique = TRUE, stringsAsFactors = FALSE)
  can <- extract_d13_candidate_universe(mem, sel, contract$candidate_set$minimum_members); gid <- match(can$gene_id, p$ids); Xtr <- t(tr[gid, , drop = FALSE]); colnames(Xtr) <- can$gene_symbol
  infold <- strat_folds(sy$OS_status[train_ix], contract$elastic_net$inner_folds, seed + sum(utf8ToInt(tag)))
  cv <- cv.glmnet(Xtr, Surv(sy$OS_time[train_ix], sy$OS_status[train_ix]), family = contract$elastic_net$family, alpha = contract$elastic_net$alpha, foldid = infold, type.measure = "C", standardize = TRUE)
  lam <- if (contract$elastic_net$lambda_rule == "lambda_1se") cv$lambda.1se else cv$lambda.min; b <- as.matrix(coef(cv, s = lam)); nz <- rownames(b)[as.vector(b) != 0]
  if (!length(nz)) stop(sprintf("FOLD_FAILURE_ZERO_FEATURE:%s", tag), call. = FALSE)
  make_pred <- function(ix, ids) { if (!length(ix)) return(NULL); cnt <- raw0[p$idx, ix, drop = FALSE]; colnames(cnt) <- ids; rownames(cnt) <- p$ids; te <- apply_v31_train_vst(fit, cnt)$transformed; rownames(te) <- p$ids; xx <- t(te[gid, , drop = FALSE]); colnames(xx) <- can$gene_symbol; as.numeric(predict(cv, newx = xx, s = lam, type = "link")) }
  list(train_prediction = as.numeric(predict(cv, newx = Xtr, s = lam, type = "link")), eval_prediction = make_pred(eval_ix, eval_ids), selected = data.frame(run_id = tag, selected_module_id = sel, module_size = nrow(can), selected_power = pw, gene_symbol = nz, coefficient = as.vector(b[nz, 1L]), stringsAsFactors = FALSE), metadata = data.frame(run_id = tag, train_n = length(train_ix), eval_n = length(eval_ix), qc_gene_n = length(p$idx), mad_gene_n = nmad, candidate_n = nrow(can), selected_n = length(nz), selected_module_id = sel, selected_power = pw, stringsAsFactors = FALSE), module_correlations = transform(long, run_id = tag), candidate_members = transform(can, run_id = tag))
}
folds <- list(); for (r in seq_len(contract$resampling$outer_repeats)) { f <- strat_folds(sy$OS_status, contract$resampling$outer_folds, seed + r); for (k in seq_len(contract$resampling$outer_folds)) folds[[length(folds) + 1L]] <- list(tr = which(f != k), te = which(f == k), tag = sprintf("R%02dF%d", r, k)) }
runtime_failure_path <- file.path(OUT, "D13_RUNTIME_FAILURE_LEDGER.tsv")
record_runtime_failure <- function(kind, run_id, reason) { x <- data.frame(timestamp_utc = format(Sys.time(), tz = "UTC", usetz = TRUE), run_type = kind, run_id = run_id, status = "FAIL", reason = reason, stringsAsFactors = FALSE); if (file.exists(runtime_failure_path)) x <- rbind(read.delim(runtime_failure_path, sep = "\t", check.names = FALSE, stringsAsFactors = FALSE), x); atomic_write_tsv(x, runtime_failure_path) }
run_checkpointed <- function(kind, ids, fun) { out <- vector("list", length(ids)); names(out) <- ids; for (j in seq_along(ids)) { path <- file.path(CP, kind, paste0(ids[[j]], ".rds")); if (file.exists(path)) { z <- readRDS(path); need(identical(z$status, "PASS"), "%s checkpoint %s records failure; fail closed", kind, ids[[j]]); out[[j]] <- z; next }; z <- tryCatch(list(status = "PASS", result = fun(j)), error = function(e) list(status = "FAIL", reason = conditionMessage(e))); atomic_write_rds(z, path); if (!identical(z$status, "PASS")) { record_runtime_failure(kind, ids[[j]], z$reason); stop(sprintf("D13_FAIL_CLOSED: %s %s failed; checkpoint retained", kind, ids[[j]]), call. = FALSE) }; out[[j]] <- z }; out }
if (identical(arg[[1L]], "--pilot")) {
  folds <- folds[1L]; z <- run_checkpointed("pilot", vapply(folds, `[[`, character(1L), "tag"), function(j) { q <- folds[[j]]; one_pipeline(q$tr, sprintf("PILOT_TRAIN_%03d_%s", seq_along(q$tr), pat[q$tr]), q$tag, q$te, sprintf("PILOT_TEST_%03d_%s", seq_along(q$te), pat[q$te])) }); ans <- lapply(z, `[[`, "result")
  pr <- do.call(rbind, Map(function(q, a) data.frame(patient_id = pat[q$te], repeat_fold = q$tag, OS_time = sy$OS_time[q$te], OS_status = sy$OS_status[q$te], linear_predictor = a$eval_prediction, stringsAsFactors = FALSE), folds, ans)); atomic_write_tsv(pr, contract$outputs$outer_predictions); atomic_write_tsv(data.frame(repeat_fold = vapply(folds, `[[`, character(1L), "tag"), status = "PASS", reason = "", stringsAsFactors = FALSE), contract$outputs$failure_ledger); writeLines(c("mode=pilot", "folds=1", sprintf("pooled_oof_concordance=%.12f", concordance_or_fail(pr$OS_time, pr$OS_status, pr$linear_predictor, "PILOT", "OOF")), "PILOT_ONLY_NOT_A_PRIMARY_RESULT"), file.path(OUT, "D13_PILOT_RECEIPT.txt")); quit(status = 0L)
}
# Stage 1: required 100 fully nested outer folds, each independently resumable.
nested <- run_checkpointed("nested", vapply(folds, `[[`, character(1L), "tag"), function(j) { q <- folds[[j]]; one_pipeline(q$tr, sprintf("NESTED_TRAIN_%03d_%s", seq_along(q$tr), pat[q$tr]), q$tag, q$te, sprintf("NESTED_TEST_%03d_%s", seq_along(q$te), pat[q$te])) }); nested_ans <- lapply(nested, `[[`, "result")
pr <- do.call(rbind, Map(function(q, a) data.frame(patient_id = pat[q$te], repeat_fold = q$tag, OS_time = sy$OS_time[q$te], OS_status = sy$OS_status[q$te], linear_predictor = a$eval_prediction, stringsAsFactors = FALSE), folds, nested_ans)); st <- do.call(rbind, lapply(nested_ans, `[[`, "selected")); mt <- do.call(rbind, lapply(nested_ans, `[[`, "metadata")); mc <- do.call(rbind, lapply(nested_ans, `[[`, "module_correlations")); cm <- do.call(rbind, lapply(nested_ans, `[[`, "candidate_members"))
atomic_write_tsv(pr, contract$outputs$outer_predictions); atomic_write_tsv(st, contract$outputs$selection_stability); atomic_write_tsv(mt, file.path(OUT, "D13_FOLD_METADATA.tsv")); atomic_write_tsv(mc, file.path(OUT, "D13_WGCNA_FOLD_MODULE_LEDGER.tsv")); atomic_write_tsv(cm, file.path(OUT, "D13_WGCNA_MEMBER_MAP.tsv"))
# Repeated held-out scores are averaged within patient before the primary nested C-index.
pm <- aggregate(linear_predictor ~ patient_id + OS_time + OS_status, data = pr, FUN = mean); need(all(table(pr$patient_id) == contract$resampling$outer_repeats), "each patient must receive exactly one held-out prediction per repeat"); nested_c <- concordance_or_fail(pm$OS_time, pm$OS_status, pm$linear_predictor, "NESTED", "OOF")
# Stage 2: final full-cohort descriptive fit, explicitly not external validation.
final <- one_pipeline(seq_along(pat), sprintf("FULL_TRAIN_%03d_%s", seq_along(pat), pat), "FULL_COHORT_DESCRIPTIVE"); final_apparent <- concordance_or_fail(sy$OS_time, sy$OS_status, final$train_prediction, "FULL_COHORT", "APPARENT")
atomic_write_tsv(data.frame(patient_id = pat, OS_time = sy$OS_time, OS_status = sy$OS_status, linear_predictor = final$train_prediction, stringsAsFactors = FALSE), file.path(OUT, "D13_SCORE_TABLE_CANDIDATE.tsv")); atomic_write_tsv(final$selected, file.path(OUT, "D13_FINAL_MODEL_COEFFICIENTS_CANDIDATE.tsv"))
# Stage 3: exactly the frozen 1,000 full-pipeline patient bootstrap fits.
boot_ids <- sprintf("B%04d", seq_len(contract$resampling$bootstrap_replicates))
boots <- run_checkpointed("bootstrap", boot_ids, function(j) { set.seed(seed + 100000L + j); ix <- sample.int(length(pat), length(pat), replace = TRUE); id <- boot_ids[[j]]; a <- one_pipeline(ix, sprintf("%s_DRAW_%03d_%s", id, seq_along(ix), pat[ix]), id, seq_along(pat), sprintf("%s_ORIG_%03d_%s", id, seq_along(pat), pat)); apparent <- concordance_or_fail(sy$OS_time[ix], sy$OS_status[ix], a$train_prediction, id, "APPARENT"); test <- concordance_or_fail(sy$OS_time, sy$OS_status, a$eval_prediction, id, "ORIGINAL_SAMPLE_TEST"); list(summary = data.frame(bootstrap_id = id, apparent_concordance = apparent, original_sample_test_concordance = test, optimism = apparent - test, selected_module_id = a$metadata$selected_module_id, candidate_n = a$metadata$candidate_n, selected_n = a$metadata$selected_n, stringsAsFactors = FALSE), selected = a$selected, metadata = a$metadata) })
bs <- do.call(rbind, lapply(boots, function(z) z$result$summary)); bsel <- do.call(rbind, lapply(boots, function(z) z$result$selected)); bmeta <- do.call(rbind, lapply(boots, function(z) z$result$metadata)); need(nrow(bs) == contract$resampling$bootstrap_replicates && all(is.finite(bs$optimism)), "bootstrap completion or estimand failure")
atomic_write_tsv(bs, contract$outputs$bootstrap_output); atomic_write_tsv(bsel, file.path(OUT, "D13_BOOTSTRAP_SELECTION_STABILITY.tsv")); atomic_write_tsv(bmeta, file.path(OUT, "D13_BOOTSTRAP_METADATA.tsv")); atomic_write_tsv(data.frame(run_type = c(rep("NESTED_OUTER", length(folds)), rep("BOOTSTRAP", length(boots))), run_id = c(vapply(folds, `[[`, character(1L), "tag"), boot_ids), status = "PASS", reason = "", stringsAsFactors = FALSE), contract$outputs$failure_ledger)
lock <- list(status = "PENDING_INDEPENDENT_VALIDATION", contract_id = contract$contract_id, nested_outer_folds = nrow(mt), nested_patient_level_oof_concordance = nested_c, full_cohort_apparent_concordance = final_apparent, bootstrap_replicates = nrow(bs), mean_optimism = mean(bs$optimism), optimism_corrected_apparent_concordance = final_apparent - mean(bs$optimism), score_table = "D13_SCORE_TABLE_CANDIDATE.tsv", coefficients = "D13_FINAL_MODEL_COEFFICIENTS_CANDIDATE.tsv", claim_ceiling = contract$outputs$final_fit_claim_ceiling, prohibition = "No score-dependent downstream analysis may use this candidate until independent validation changes status to VALIDATED_MODEL_LOCK.")
tmp_lock <- paste0(contract$outputs$model_lock, ".tmp-", Sys.getpid()); jsonlite::write_json(lock, tmp_lock, auto_unbox = TRUE, pretty = TRUE); need(file.rename(tmp_lock, contract$outputs$model_lock), "cannot atomically install candidate model lock")
writeLines(c("mode=execute", sprintf("nested_outer_folds=%d", nrow(mt)), sprintf("nested_patient_level_oof_concordance=%.12f", nested_c), sprintf("full_cohort_apparent_concordance=%.12f", final_apparent), sprintf("bootstrap_replicates=%d", nrow(bs)), sprintf("mean_optimism=%.12f", mean(bs$optimism)), "MODEL_LOCK_STATUS=PENDING_INDEPENDENT_VALIDATION"), file.path(OUT, "D13_EXECUTION_RECEIPT.txt"))
